// Lecture integrale article - screening approfondi sur PDF complet
// FULLTEXT_SCREENING_v1 (v0.2.6)
const PROXY = 'http://host.docker.internal:3456';
const items = $input.all();
const articles = items.map(i => i.json);
const question = (articles[0] && articles[0].question) || '';
const criteria = (articles[0] && articles[0].criteria) || '';
// FULLTEXT_AI_SETTINGS_v1 - reutilise les reglages avances du screening (strictesse + regles)
let __ftAi = (articles[0] && articles[0]._ai_settings) || {};
if (typeof __ftAi.strictness !== 'number') { try { const __fc = await this.helpers.httpRequest({ method:'GET', url:'http://host.docker.internal:8080/api/config', timeout:5000, json:true }) || {}; __ftAi = { strictness: __fc.fulltext_strictness, custom_rules: __fc.fulltext_custom_rules }; } catch(e) {} }
const __ftStrict = (typeof __ftAi.strictness === 'number') ? __ftAi.strictness : 50;
const __ftRules = (__ftAi.custom_rules || '').toString().trim();
let __ftGuidance = '';
if (__ftStrict <= 25) __ftGuidance = '\n\nTONE: Be CONSERVATIVE - when in doubt, prefer Include or Maybe over Exclude.';
else if (__ftStrict >= 75) __ftGuidance = '\n\nTONE: Be STRICT - only Include if ALL criteria are clearly met in the full text; when in doubt, Exclude.';
else if (__ftStrict >= 60) __ftGuidance = '\n\nTONE: Slightly strict - when in doubt, lean toward Exclude.';
else if (__ftStrict <= 40) __ftGuidance = '\n\nTONE: Slightly conservative - when in doubt, lean toward Maybe.';
const __ftRulesBlock = __ftRules ? ('\n\n=== USER-DEFINED RULES (must be respected) ===\n' + __ftRules) : '';

// LECTURE_MESUREE_v1 (mesure du 2026-09-10) : UN SEUL ANALYSEUR pour les deux decisions de la
// double lecture. La seconde decision passait par un repli laxiste (le premier des trois mots
// trouve dans la reponse) et echappait a la regle « Include sans justification devient Maybe » :
// sur les memes reponses de modele, le noeud double mesurait 5 paires et kappa 0,333, le second
// avis du moteur (qui rejoue CE noeud avec le modele 2 en premier modele) 4 paires et kappa
// 0,636. Une phrase libre concluant a l'exclusion (« ... does not include the target population;
// it should be excluded. ») y valait Include et formait une paire en accord. Rend
// { decision, reason }, ou null quand la reponse ne porte aucune ligne « Decision » lisible.
function __ftLire(raw) {
  const s = String(raw || '');
  const m = s.match(/decision[\s:=]+(include|maybe|exclude)/i);
  if (!m) return null;
  const w = m[1].toLowerCase();
  let d = w.indexOf('inc') === 0 ? 'Include' : (w.indexOf('exc') === 0 ? 'Exclude' : 'Maybe');
  let r = '';
  const rm = s.match(/reason[\s:=]+([\s\S]{0,2000})/i);
  if (rm) r = rm[1].split(/\n\n|\r\n\r\n/)[0].split(/\ncategory/i)[0].trim().substring(0, 2000);
  // Securite : si pas de reason et qu'on a une decision, marquer
  if (!r) r = '(no reason returned)';
  // Securite scientifique : Include sans reason -> Maybe (cf v0.2.5 #37)
  if (d === 'Include' && /^\(no reason/i.test(r)) {
    d = 'Maybe';
    r = 'LLM a propose Include mais sans justification verifiable - reclasse Maybe pour verification manuelle';
  }
  return { decision: d, reason: r };
}

console.log('[Fulltext Screening] ' + articles.length + ' articles candidats');

// SECONDE_LECTURE_DE_CETTE_EXECUTION_v1 (refutation P2, mesure du 2026-09-10) : une seconde
// lecture ne vaut que face a la premiere lecture de la MEME execution. Le planificateur charge un
// dossier de run comme corpus (pipeline._articles_from_folder) et ne retire que les cles a tiret
// bas : la seconde lecture, l'etiquette d'accord et le modele 2 d'un run A double entraient dans
// une lecture B. Lue en simple, B ressortait avec les 4 secondes lectures de A ; doublee, avec le
// modele 2 en echec sur 2 rapports, elle en portait 4 pour 2 paires mesurees, et le moteur, qui
// recalcule l'accord depuis ces champs, publiait kappa 0,0 au lieu de 1,0. Ils sont retires ICI,
// de chaque article, quelle que soit sa branche : c'est la seule protection, la notice sautee et
// la reponse du modele 2 n'en ont plus de propre. Cout accepte : un rapport repris dont le modele
// 2 echoue a la reprise perd sa paire. screening_model2 reste (le tri sur resume, l'extraction
// et le second avis l'ecrivent aussi) : sans seconde decision, il ne forme aucune paire.
// LA TRACE D'ARBITRAGE D'UN AUTRE RUN AUSSI (refutation P3, mesure du 2026-09-10). L'arbitrage
// humain d'un desaccord de A (server._muter_decision_article) pose
// screening_decision_fulltext_original, la decision du modele 1 de A : sans tiret bas, elle
// traverse le chargeur, son drapeau _human_corrected non. Le moteur la lisait comme la decision
// du modele 1 de B : B mesurait 4 paires et 4 accords (kappa 1), l'item 8 publiait 1 desaccord
// et kappa 0,5, ou 0,6 quand le registre reposait sur B la decision de A (il garde la trace
// qu'il trouve). Une trace sans son drapeau n'est pas une decision humaine de CETTE execution :
// meme signe que __humain (NOTICE_SAUTEE_v1) et __humainFT (statsInto). Avec son drapeau
// (reprise du run corrige), elle reste.
for (let __e = 0; __e < articles.length; __e++) { const __a = articles[__e]; if (__a && typeof __a === 'object') { delete __a.screening_decision_fulltext_2; delete __a._screening_decision_fulltext_2_repli; delete __a.screening_agreement_fulltext; if (!__a._human_corrected) delete __a.screening_decision_fulltext_original; } }

const results = [];
const stats = { total: articles.length, eligible: 0, confirmed: 0, revised: 0, no_pdf: 0, no_decision: 0, extract_failed: 0 };

for (let i = 0; i < articles.length; i++) {
  const article = articles[i];
  const orig_decision = article.screening_decision || '';
  const pdf_path = article.pdf_local || '';

  // FULLTEXT_ELIGIBILITY_v2 : on analyse tout SAUF les Exclude deja decides
  // (permet le screening direct depuis dossier de PDFs sans pre-screening)
  if (orig_decision === 'Exclude') {
    // NOTICE_SAUTEE_v1 (mesure du 2026-09-10) : une notice sautee n'a pas ete lue par CETTE
    // execution. Elle arrivait avec les champs d'une lecture anterieure (reprise de tout le
    // corpus apres qu'une decision sur resume l'a exclue) et les gardait : statut « confirmed »,
    // decision Include, si bien que l'assemblage publiait 2 articles evalues et 2 inclus pour
    // une seule lecture reelle. Ces champs sont retires ici ; ceux de la seconde lecture l'ont
    // deja ete a l'entree du noeud (SECONDE_LECTURE_DE_CETTE_EXECUTION_v1). SEULE EXCEPTION : une
    // decision HUMAINE sur texte integral (trace screening_decision_fulltext_original posee par la
    // correction), qu'on ne perd pas ; son statut de lecture, lui, part.
    const __saut = Object.assign({}, article, {
      _fulltext_skipped: 'already excluded by pre-screening'
    });
    const __humain = !!__saut._human_corrected && ('screening_decision_fulltext_original' in __saut);
    const __perimes = ['_fulltext_status'];
    if (!__humain) __perimes.push('screening_decision_fulltext');
    for (let __p = 0; __p < __perimes.length; __p++) delete __saut[__perimes[__p]];
    results.push({ json: __saut });
    continue;
  }

  if (!pdf_path) {
    stats.no_pdf++;
    results.push({ json: Object.assign({}, article, {
      screening_decision_fulltext: orig_decision,
      screening_reason_fulltext: 'PDF non disponible - decision initiale conservee',
      screening_decision_initial: orig_decision,
      _fulltext_status: 'no_pdf'
    })});
    continue;
  }

  stats.eligible++;

  // === 1. Extract PDF text ===
  let full_text = '';
  try {
    const resp = await this.helpers.httpRequest({
      method: 'POST',
      url: PROXY + '/extract-pdf',
      body: JSON.stringify({ pdf_path: pdf_path, max_chars: 30000, skip_biblio: true }),
      headers: { 'Content-Type': 'application/json' },
      json: true,
      timeout: 60000
    });
    if (resp && resp.success && resp.text) {
      full_text = resp.text.substring(0, 25000);
    } else {
      throw new Error((resp && resp.error) || 'PDF extraction failed');
    }
  } catch (e) {
    stats.extract_failed++;
    results.push({ json: Object.assign({}, article, {
      screening_decision_fulltext: orig_decision,
      screening_reason_fulltext: 'PDF extraction failed: ' + (e.message || e),
      screening_decision_initial: orig_decision,
      _fulltext_status: 'extract_failed'
    })});
    continue;
  }

    // FULLTEXT_METADATA_ENRICH_v3 - extraction automatique DOI + annee depuis le PDF
    if (!article.doi && full_text) {
      const doiMatch = full_text.substring(0, 8000).match(/\b10\.\d{4,9}\/[-._;()/:A-Z0-9]+/i);
      if (doiMatch) {
        // Nettoie la fin du DOI (point final, virgule, parenthese, etc.)
        article.doi = doiMatch[0].replace(/[.,;)\]]+$/, '');
      }
    }
    if (!article.year && full_text) {
      // Cherche annee en contexte editorial dans les premiers 6000 chars
      const ctxMatch = full_text.substring(0, 6000).match(/(?:received|accepted|published|copyright|year|date|\bPublished:?\b|©)\s*[:\-]?\s*.{0,40}?(19\d{2}|20[0-3]\d)/i);
      if (ctxMatch) {
        article.year = ctxMatch[1];
      } else {
        // Fallback : premiere annee plausible dans les 3000 premiers chars
        const yMatch = full_text.substring(0, 3000).match(/\b(19\d{2}|20[0-3]\d)\b/);
        if (yMatch) article.year = yMatch[1];
      }
    }
    // Nettoyer le titre : espaces multiples -> simple (utile pour les titres
    // generes depuis nom de fichier qui contiennent souvent '   ')
    if (article.title) {
      article.title = article.title.replace(/\s+/g, ' ').trim();
    }

  // FULLTEXT_CROSSREF_ENRICH_v1 - completer authors/journal/annee/abstract via Crossref par DOI
  if (article.doi && (!article.authors || article.authors.length === 0 || !article.journal || !article.abstract)) {
    try {
      const _crUrl = 'https://api.crossref.org/works/' + encodeURIComponent(article.doi);
      const _cr = await this.helpers.httpRequest({
        method: 'GET',
        url: PROXY + '?url=' + encodeURIComponent(_crUrl),
        json: true,
        timeout: 20000
      });
      const _m = _cr && _cr.message;
      if (_m) {
        const _crTitle = (Array.isArray(_m.title) && _m.title[0]) ? _m.title[0] : '';
        // Filet anti-mauvais-DOI : recoupement du titre courant vs Crossref
        function _toks(t){ return (t||'').toLowerCase().replace(/[^a-z0-9 ]/g,' ').split(/\s+/).filter(function(w){ return w.length > 3; }); }
        const _a = _toks(article.title), _b = _toks(_crTitle);
        let _match = 0;
        for (let _k = 0; _k < _a.length; _k++) { if (_b.indexOf(_a[_k]) >= 0) _match++; }
        const _ratio = _b.length ? (_match / Math.min(_a.length || 1, _b.length)) : 0;
        const _trust = (!article.title) || (_a.length === 0) || (_ratio >= 0.34);
        if (_trust) {
          if ((!article.authors || article.authors.length === 0) && Array.isArray(_m.author)) {
            article.authors = _m.author.map(function(au){ return [au.given, au.family].filter(Boolean).join(' ') || au.name || ''; }).filter(Boolean);
          }
          if (!article.journal && Array.isArray(_m['container-title']) && _m['container-title'].length) {
            article.journal = _m['container-title'][0];
          }
          if (_crTitle) { article.title = _crTitle; }
          const _dp = (_m.issued && _m.issued['date-parts']) || (_m.published && _m.published['date-parts']) || null;
          if (_dp && _dp[0] && _dp[0][0]) { article.year = String(_dp[0][0]); }
          if (!article.abstract && _m.abstract) {
            article.abstract = _m.abstract.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
          }
          article._crossref_enriched = true;
        } else {
          article._crossref_status = 'doi_title_mismatch';
          console.log('[Fulltext Crossref] DOI/titre incoherent, enrich ignore: ' + article.doi);
        }
      }
    } catch (_e) {
      console.log('[Fulltext Crossref] enrich failed for ' + article.doi + ': ' + (_e.message || _e));
    }
  }

  // === 2. Build prompt + Call LLM ===
  const title = (article.title || '').substring(0, 200);
  const prompt =
    'You are a systematic review screener performing in-depth full-text analysis.\n\n' +
    'RESEARCH QUESTION:\n' + question.substring(0, 500) + '\n\n' +
    'INCLUSION/EXCLUSION CRITERIA:\n' + criteria.substring(0, 500) + __ftGuidance + __ftRulesBlock + '\n\n' +
    '=== ARTICLE FULL TEXT ===\n' +
    'TITLE: ' + title + '\n\n' +
    'FULL TEXT (truncated to first 25000 chars, bibliography removed):\n' + full_text + '\n\n' +
    '=== INITIAL DECISION (abstract-only pre-screening) ===\n' +
    orig_decision + '\n\n' +
    '=== YOUR TASK ===\n' +
    'Reconsider the decision based on the FULL TEXT (not just the abstract). ' +
    'You may confirm or change the initial decision. Output EXACTLY 3 lines:\n' +
    'Line 1 - Decision: followed by exactly one word among Include, Maybe, Exclude.\n' +
    'Line 2 - Reason: followed by one short sentence based on what you read in the full text.\n' +
    'Line 3 - Category: if your Decision is Exclude, pick the ONE reason that best explains the exclusion, copied EXACTLY from this list: ' +
    'wrong population, wrong intervention, wrong comparator, wrong outcome, wrong study design, not a primary study, duplicate, wrong language, insufficient data, other. ' +
    'If your Decision is Include or Maybe, write exactly: none\n\n' +
    'All 3 lines are mandatory, in this order, no blank line between them. ' +
    'No markdown. No explanation before or after. Start IMMEDIATELY with "Decision:".';

  try {
    const ollamaResp = await this.helpers.httpRequest({
      method: 'POST',
      url: PROXY + '/api/generate',
      body: JSON.stringify({
        model: 'qwen2.5:3b',
        prompt: prompt,
        stream: false,
        options: {
          temperature: 0,
          num_predict: 800,
          num_ctx: 32768,
          stop: ['\n\n\n', 'Article ', 'TITLE:', 'Article:']
        },
        keep_alive: '30m',
        _ultralab_task: 'chat'
      }),
      headers: { 'Content-Type': 'application/json' },
      json: true,
      timeout: 900000
    });
    const raw = (ollamaResp && ollamaResp.response) || '';
    // LECTURE_MESUREE_v1 (2026-09-10) : la decision passe par __ftLire, l'analyseur qu'emprunte
    // aussi la seconde decision de la double lecture (voir sa definition, en tete du noeud).
    const decMatch = __ftLire(raw);
    let new_decision = orig_decision;
    let new_reason = '';
    if (decMatch) {
      new_decision = decMatch.decision;
      new_reason = decMatch.reason;
    } else {
      stats.no_decision++;
      new_reason = 'LLM did not return parseable decision - kept initial decision [raw: ' + raw.substring(0, 150).replace(/\s+/g, ' ') + ']';
    }
    // EXCL_TAXONOMY_v1 (F1) - motif d exclusion standardise PRISMA 2020 : le LLM choisit dans
    // une liste FERMEE, normalisation par mots-cles ici (categories stables -> comptage fiable).
    let exclusion_category = '';
    if (new_decision === 'Exclude') {
      const catMatch = raw.match(/category[\s:=]+([^\n]{0,80})/i);
      const rawCat = (catMatch ? catMatch[1] : '').toLowerCase();
      const CANON = [
        ['wrong population', ['populat', 'patient', 'participant', 'age group', 'pediatric', 'animal']],
        ['wrong intervention', ['interven', 'exposure', 'treatment', 'therapy']],
        ['wrong comparator', ['compar', 'control group']],
        ['wrong outcome', ['outcome', 'endpoint']],
        ['wrong study design', ['design', 'study type', 'case report', 'protocol']],
        ['not a primary study', ['primary', 'review', 'editorial', 'commentary', 'letter']],
        ['duplicate', ['duplic']],
        ['wrong language', ['language', 'langue']],
        ['insufficient data', ['insufficient', 'usable data', 'not reported', 'incomplete']],
      ];
      for (let ci = 0; ci < CANON.length && !exclusion_category; ci++) {
        for (let ki = 0; ki < CANON[ci][1].length; ki++) {
          if (rawCat.indexOf(CANON[ci][1][ki]) >= 0) { exclusion_category = CANON[ci][0]; break; }
        }
      }
      if (!exclusion_category) exclusion_category = 'other';
      stats.exclusion_categories = stats.exclusion_categories || {};
      stats.exclusion_categories[exclusion_category] = (stats.exclusion_categories[exclusion_category] || 0) + 1;
    }
    // LECTURE_ILLISIBLE_v1 (mesure du 2026-09-10) : une reponse sans decision lisible n'est PAS
    // une lecture. La decision du tri sur resume est recopiee a cote, et le statut disait
    // « confirmed » : la notice passait pour relue sur texte integral, entrait dans les paires
    // de la double lecture et gonflait l'accord, le second modele partant de la meme decision
    // initiale. Elle porte desormais le statut d'echec d'appel, celui que le moteur reconnait
    // deja (run_resume : ECHECS_FULLTEXT pour la reprise, hors LECTURES_REUSSIES pour les
    // paires) et que l'assemblage compte parmi les « non analyses ». Un statut neuf aurait
    // disparu de ces trois comptes.
    const __ftLu = !!decMatch;
    if (new_decision === orig_decision) stats.confirmed++; else stats.revised++;
    results.push({ json: Object.assign({}, article, {
      screening_decision_fulltext: new_decision,
      screening_reason_fulltext: new_reason,
      exclusion_category: exclusion_category || undefined,
      screening_decision_initial: orig_decision,
      _fulltext_status: !__ftLu ? 'llm_error' : (new_decision === orig_decision ? 'confirmed' : 'revised'),
      _fulltext_raw_preview: raw.substring(0, 250).replace(/\s+/g, ' '),
      _ft_prompt: prompt
    })});
  } catch (e) {
    stats.no_decision++;
    results.push({ json: Object.assign({}, article, {
      screening_decision_fulltext: orig_decision,
      screening_reason_fulltext: 'LLM call error: ' + (e.message || e),
      screening_decision_initial: orig_decision,
      _fulltext_status: 'llm_error'
    })});
  }
}

console.log('[Fulltext Screening] Stats: ' + JSON.stringify(stats));

// FULLTEXT_DOUBLE_KAPPA_v1 - 2e relecture fulltext (modele OBLIGATOIREMENT different) + kappa, opt-in (config screening)
// FULLTEXT_DOUBLE_KAPPA_v2 (2026-09-10) : le bloc d'accord decrit CETTE execution, et seulement
// si elle a mesure quelque chose. Un bloc herite est d'abord retire : la reprise renvoie ici les
// articles tels qu'ils sont sur le disque, bloc compris, et il traversait jusqu'au fichier de
// methodes sous le nom d'une execution qui ne l'avait pas mesure.
for (let __s=0; __s<results.length; __s++){ if (results[__s].json && ('_fulltext_kappa' in results[__s].json)) delete results[__s].json._fulltext_kappa; }
try {
  let __cfg = {};
  try { __cfg = await this.helpers.httpRequest({ method:'GET', url:'http://host.docker.internal:8080/api/config', timeout:5000, json:true }) || {}; } catch(e) {}
  const __dblOn = __cfg.screening_double_enabled === true;
  const __m1 = (__cfg.ollama_model||'').trim();
  const __m2 = (__cfg.screening_model_2||'').trim();
  if (__dblOn && __m2 && __m2 !== __m1) {
    function __pd(raw){ if(!raw) return null; let m=String(raw).match(/decision[\s:=]+(include|maybe|exclude)/i); if(!m) m=String(raw).match(/\b(include|maybe|exclude)\b/i); if(!m) return null; const w=m[1].toLowerCase(); return w.indexOf('inc')===0?'Include':(w.indexOf('exc')===0?'Exclude':'Maybe'); }
    const __cats=['Include','Maybe','Exclude']; const __c1={Include:0,Maybe:0,Exclude:0},__c2={Include:0,Maybe:0,Exclude:0}; let __nb=0,__ag=0;
    // UNE PAIRE PART D'UNE VRAIE LECTURE DU PREMIER MODELE, meme regle que le moteur
    // (run_resume._decision_d_origine) : statut de lecture reussie, decision dans les trois
    // categories. Le second avis peut toujours etre demande sur les autres (il renseigne
    // l'arbitrage), mais il n'entre pas dans la mesure de l'accord. LA NOTICE SAUTEE n'a plus de
    // condition propre ici (2026-09-10) : sa branche retire son statut (NOTICE_SAUTEE_v1), et une
    // seconde condition couvrant le meme cas ne serait eprouvee par aucun test.
    function __ftLuTexte(r){ return (r._fulltext_status==='confirmed' || r._fulltext_status==='revised') && __cats.indexOf(r.screening_decision_fulltext)>=0; }
    // SUR COMBIEN : les lectures reussies du premier modele, comme n_first_rated du moteur.
    let __n1=0; for (let __q=0; __q<results.length; __q++){ if (__ftLuTexte(results[__q].json)) __n1++; }
    for (let __i=0; __i<results.length; __i++) {
      const __r = results[__i].json;
      if (!__r._ft_prompt || !__r.screening_decision_fulltext) continue;
      let __raw2='';
      try {
        const __rp = await this.helpers.httpRequest({ method:'POST', url:PROXY+'/api/generate', body: JSON.stringify({ model:__m2, prompt:__r._ft_prompt, stream:false, options:{temperature:0,num_predict:800,num_ctx:32768,stop:['\n\n\n','Article ','TITLE:','Article:']}, keep_alive:'30m', _ultralab_task:'screening_pass2' }), headers:{'Content-Type':'application/json'}, json:true, timeout:900000 });
        __raw2 = (__rp && __rp.response) || '';
      } catch(e) {}
      // LECTURE_MESUREE_v1 (2026-09-10). LA SECONDE DECISION MESUREE passe par __ftLire, comme la
      // premiere : c'est elle, et elle seule, que porte screening_decision_fulltext_2, le champ que
      // relit le moteur pour recalculer l'accord. LE REPLI LAXISTE (__pd) reste pour l'arbitrage :
      // sa lecture va dans _screening_decision_fulltext_2_repli, hors de la mesure. Les champs d'une
      // reponse anterieure du modele 2 ne sont plus retires ici : ils l'ont ete a l'entree du
      // noeud, de chaque article (SECONDE_LECTURE_DE_CETTE_EXECUTION_v1).
      const __l2 = __ftLire(__raw2);
      const __d2m = __l2 ? __l2.decision : null;
      const __d2r = __d2m ? null : __pd(__raw2);
      const __d2 = __d2m || __d2r;
      if (__d2) {
        if (__d2m) __r.screening_decision_fulltext_2 = __d2m; else __r._screening_decision_fulltext_2_repli = __d2r;
        __r.screening_model2 = __m2;
        const __d1 = __r.screening_decision_fulltext;
        const __lu1 = __ftLuTexte(__r);
        const __mes = __lu1 && !!__d2m;
        // « agree » SEULEMENT POUR UNE PAIRE MESUREE (2026-09-10). Une reponse illisible du modele 1
        // recopie la decision du resume : quand le modele 2 tombait sur la meme, la notice sortait
        // « agree », sans arbitrage, alors qu'un seul modele avait lu le rapport. Une notice qui
        // n'est pas une lecture part desormais en arbitrage des que le modele 2 a rendu une decision.
        // DRAPEAU D'ARBITRAGE ANTERIEUR, DOCUMENTE ET NON CORRIGE (refutation H5 du 2026-09-10) : un
        // accord mesure ici ne retire pas un _needs_human_review deja present. Le noeud ne sait pas
        // qui l'a pose : une execution anterieure de ce noeud (non-lecture du modele 1, desaccord),
        // le tri sur resume, ou une correction. Le retirer pourrait effacer une demande d'arbitrage
        // legitime ; le garder coute au pire une relecture humaine de trop (human_review compte la
        // notice « a arbitrer »), jamais un accord affirme a tort. Sens prudent, choisi.
        if (__d2 !== __d1) { __r.screening_agreement_fulltext = 'disagree'; __r._needs_human_review = true; }
        else if (__mes) __r.screening_agreement_fulltext = 'agree';
        else if (!__lu1) __r._needs_human_review = true;
